# Let me understand the pattern better by looking at what exactly changes
inputs = ['zzzbfk', 'zvdb', 'bdbai', 'iyik', 'gz']
outputs = ['zzzbfk', 'zvdb', 'bdbaek', 'ibiyibik', 'gz']

print("Input -> Output differences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_pos = []
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos.append(j)
        if len(out) > len(inp):
            diff_pos.extend(range(len(inp), len(out)))
        elif len(inp) > len(out):
            diff_pos.extend(range(len(out), len(inp)))
        print(f"  Differences at positions: {diff_pos}")
    print()

